<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {api} from './api';import Icon from './Icon.vue';
const props=withDefaults(defineProps<{item:any;standalone?:boolean;shareToken?:string;fluidDesktop?:boolean}>(),{standalone:false});
const device=ref('pc'),viewport=ref<HTMLElement>(),frame=ref<HTMLIFrameElement>(),available=ref(280),ready=ref(false),error=ref(''),loading=ref(false),reload=ref(0);
const width=computed(()=>device.value==='pc'?(props.fluidDesktop?Math.max(1024,Math.floor(available.value)):1280):390),height=computed(()=>device.value==='pc'?800:844),scale=computed(()=>Math.min(1,Math.max(1,available.value)/width.value));
const endpoint=computed(()=>props.shareToken?'/share/'+props.shareToken:'/items/'+props.item.id);
const url=computed(()=>`/preview/${props.item.id}?device=${device.value}`);
let observer:ResizeObserver,sequence=0;
async function load(){const n=++sequence;ready.value=false;error.value='';loading.value=true;try{if(!props.shareToken)await api(endpoint.value+'/preview');if(n===sequence){ready.value=true;reload.value++;}}catch(e:any){if(n===sequence)error.value=e.message;}finally{if(n===sequence)loading.value=false;}}
async function bridge(e:MessageEvent){const source=frame.value?.contentWindow;if(!source||e.source!==source||e.data?.type!=='pm-data')return;const {requestId,action,collection,data,id}=e.data;const itemId=props.item.id;try{if(props.shareToken&&action!=='list')throw new Error('分享预览仅可读取数据，不能修改项目数据');const result=await api(endpoint.value+'/data','POST',{action,collection,data,id});if(frame.value?.contentWindow===source&&props.item.id===itemId)source.postMessage({type:'pm-data-result',requestId,result},'*');}catch(e:any){if(frame.value?.contentWindow===source&&props.item.id===itemId)source.postMessage({type:'pm-data-result',requestId,error:e.message},'*');}}
watch(()=>[props.item.id,props.item.version],load);
onMounted(()=>{if(props.standalone&&new URLSearchParams(location.search).get('device')==='phone')device.value='phone';window.addEventListener('message',bridge);observer=new ResizeObserver(entries=>{available.value=entries[0].contentRect.width;});if(viewport.value)observer.observe(viewport.value);load();});
onUnmounted(()=>{sequence++;observer?.disconnect();window.removeEventListener('message',bridge);});
</script>
<template><section class="prototype-player" :class="{'standalone-player':standalone}"><div class="prototype-player-toolbar"><div class="view-switch"><button :class="{active:device==='pc'}" :aria-pressed="device==='pc'" @click="device='pc'"><Icon name="Monitor" :size="15"/>PC 端</button><button :class="{active:device==='phone'}" :aria-pressed="device==='phone'" @click="device='phone'"><Icon name="Smartphone" :size="15"/>手机端</button></div><a v-if="!standalone" :href="url" target="_blank" rel="noopener noreferrer" class="text-button accent"><Icon name="ExternalLink" :size="14"/>新窗口交互</a><button v-else class="text-button" @click="load" :disabled="loading"><Icon name="RefreshCw" :size="14"/>刷新预览</button></div><p class="prototype-viewport-label">{{width}} × {{height}} · {{Math.round(scale*100)}}%<span v-if="!standalone"> · 可在新窗口放大操作</span></p><div ref="viewport" class="prototype-viewport"><div v-if="loading" class="empty-mini">正在准备预览…</div><div v-else-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div v-else-if="ready" class="prototype-scaled-canvas" :style="{width:width*scale+'px',height:height*scale+'px'}"><iframe :key="item.id+':'+item.version+':'+reload" ref="frame" :src="`/api${endpoint}/render?v=${item.version}`" sandbox="allow-scripts allow-forms" title="创作成果预览" :style="{width:width+'px',height:height+'px',transform:`scale(${scale})`}"/></div></div></section></template>
